sp_widget.client_script:
api.controller = function($scope, $timeout) {

    var c = this;

    c.processing = false;

    c.actionMessage = "";
    c.actionType = "";


    // -----------------------------------
    // SHOW INLINE MESSAGE
    // -----------------------------------

    c.showMessage = function(message, type) {

        c.actionMessage = message;
        c.actionType = type;

        // Optional: automatically hide after 5 seconds
        $timeout(function() {
            c.actionMessage = "";
            c.actionType = "";
        }, 5000);
    };


    // -----------------------------------
    // APPROVE
    // -----------------------------------

    c.approve = function(item) {

        if (c.processing)
            return;

        c.processing = true;

        c.server.get({

            action: 'approve',

            sys_id: item.sys_id,

            remarks: item.remarks || ""

        }).then(function(response) {

            c.processing = false;

            if (response.data.success) {

                c.showMessage(
                    response.data.message,
                    "success"
                );

                c.data.requests =
                    response.data.requests;

            } else {

                c.showMessage(
                    response.data.message ||
                    "Unable to approve request.",
                    "error"
                );
            }

        });
    };


    // -----------------------------------
    // REJECT
    // -----------------------------------

    c.reject = function(item) {

        if (c.processing)
            return;

        if (!item.remarks ||
            item.remarks.trim() == "") {

            c.showMessage(
                "Please enter HOD remarks before rejecting.",
                "error"
            );

            return;
        }


        c.processing = true;

        c.server.get({

            action: 'reject',

            sys_id: item.sys_id,

            remarks: item.remarks

        }).then(function(response) {

            c.processing = false;

            if (response.data.success) {

                c.showMessage(
                    response.data.message,
                    "success"
                );

                c.data.requests =
                    response.data.requests;

            } else {

                c.showMessage(
                    response.data.message ||
                    "Unable to reject request.",
                    "error"
                );
            }

        });
    };

};

sp_widget.css:
/* ========================================
   MAIN PAGE
   ======================================== */

.hod-approvals-page {
  max-width: 1100px;
  margin: 0 auto;
  padding: 22px 20px 50px 20px;
  font-family: inherit;
  color: #0f172a;
}


/* ========================================
   PAGE HEADER
   ======================================== */

.page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;

  padding-bottom: 14px;
  margin-bottom: 22px;

  border-bottom: 1px solid #e5e7eb;
}


.page-header h2 {
  margin: 0;

  font-size: 29px;
  font-weight: 700;

  color: #172554;
}


.page-header p {
  margin: 6px 0 0 0;

  color: #64748b;
  font-size: 14px;
}


.back-link {
  margin-top: 10px;

  color: #2563eb;
  font-size: 14px;

  text-decoration: none;
}


.back-link:hover {
  color: #1d4ed8;
  text-decoration: underline;
}


/* ========================================
   ACTION MESSAGES
   ======================================== */

.hod-action-message {
  display: flex;
  align-items: flex-start;
  gap: 12px;

  margin-bottom: 20px;

  padding: 14px 16px;

  border-radius: 10px;

  font-size: 14px;
}


.hod-action-message .message-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 25px;
  height: 25px;

  min-width: 25px;

  border-radius: 50%;

  font-size: 14px;
  font-weight: 700;
}


.hod-action-message.success {
  background: #ecfdf5;
  border: 1px solid #a7f3d0;
  color: #065f46;
}


.hod-action-message.success .message-icon {
  background: #10b981;
  color: #ffffff;
}


.hod-action-message.error {
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #991b1b;
}


.hod-action-message.error .message-icon {
  background: #ef4444;
  color: #ffffff;
}


/* ========================================
   SUMMARY CARD
   ======================================== */

.summary-card {
  display: inline-flex;

  align-items: center;
  gap: 18px;

  background: #ffffff;

  border: 1px solid #dbe3ec;
  border-radius: 12px;

  padding: 17px 20px;

  margin-bottom: 22px;

  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
}


.summary-label {
  font-size: 14px;
  font-weight: 600;

  color: #172554;
}


.summary-value {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 31px;
  height: 31px;

  padding: 0 8px;

  border-radius: 50%;

  background: #fff7e6;

  color: #d97706;

  font-size: 14px;
  font-weight: 600;
}


/* ========================================
   APPROVAL CARD
   ======================================== */

.approval-card {
  background: #ffffff;

  border: 1px solid #dbe3ec;
  border-radius: 14px;

  padding: 20px 22px;

  margin-bottom: 22px;

  box-shadow:
    0 2px 6px rgba(15, 23, 42, 0.04);
}


/* ========================================
   CARD TOP
   ======================================== */

.approval-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 16px;

  padding-bottom: 16px;
  margin-bottom: 18px;

  border-bottom: 1px solid #e7ebf0;
}


.approval-top h3 {
  margin: 0 0 4px 0;

  font-size: 19px;
  font-weight: 600;

  color: #172554;
}


.request-number {
  font-size: 13px;
  color: #64748b;
}


.status-pill {
  display: inline-flex;
  align-items: center;

  padding: 6px 12px;

  border-radius: 20px;

  background: #fff4df;

  color: #d97706;

  font-size: 12px;
  font-weight: 600;
}


/* ========================================
   DETAILS GRID
   ======================================== */

.details-grid {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 15px;

  margin-bottom: 19px;
}


.detail-item {
  background: #f8fafc;

  border-radius: 9px;

  padding: 13px 14px;

  min-height: 62px;
}


.detail-item span {
  display: block;

  margin-bottom: 5px;

  color: #64748b;

  font-size: 12px;
}


.detail-item strong {
  display: block;

  color: #172554;

  font-size: 14px;
  font-weight: 600;
}


/* ========================================
   REASON
   ======================================== */

.reason-box {
  margin-top: 2px;
  margin-bottom: 18px;
}


.section-label,
.reason-box > span {
  display: block;

  margin-bottom: 6px;

  color: #64748b;

  font-size: 13px;
  font-weight: 500;
}


.reason-box p {
  margin: 0;

  color: #172554;

  font-size: 14px;
  line-height: 1.5;

  white-space: pre-wrap;
}


/* ========================================
   SUPPORTING DOCUMENTS
   ======================================== */

.attachments-box {
  margin-top: 20px;
  margin-bottom: 22px;

  padding-top: 18px;

  border-top: 1px solid #edf0f4;
}


.attachments-header {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 12px;
}


.attachments-heading {
  display: flex;
  align-items: center;
}


.attachment-title {
  color: #172554;

  font-size: 14px;
  font-weight: 600;
}


.attachment-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 24px;
  height: 24px;

  padding: 0 7px;
  margin-left: 8px;

  border-radius: 50px;

  background: #eaf1ff;

  color: #2563eb;

  font-size: 12px;
  font-weight: 600;
}


/* ========================================
   ATTACHMENT CARD
   ======================================== */

.attachment-card {
  overflow: hidden;

  margin-bottom: 14px;

  padding: 14px;

  background: #f8fafc;

  border: 1px solid #dbe3ec;
  border-radius: 11px;
}


/* ========================================
   ATTACHMENT FILE HEADER
   ======================================== */

.attachment-file-header {
  display: flex;
  align-items: center;

  gap: 11px;

  margin-bottom: 13px;
}


.attachment-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 38px;
  height: 38px;

  min-width: 38px;

  border-radius: 9px;

  background: #e0f2fe;

  color: #0369a1;

  font-size: 16px;
}


.attachment-file-details {
  display: flex;
  flex-direction: column;

  min-width: 0;
}


.attachment-name {
  color: #172554;

  font-size: 14px;
  font-weight: 600;

  word-break: break-word;
}


.attachment-size {
  margin-top: 3px;

  color: #64748b;

  font-size: 12px;
}


/* ========================================
   IMAGE PREVIEW
   ======================================== */

.image-preview-wrapper {
  width: 100%;

  padding: 12px;

  background: #ffffff;

  border: 1px solid #e2e8f0;
  border-radius: 9px;

  text-align: center;
}


.attachment-image {
  display: block;

  width: auto;
  height: auto;

  max-width: 520px;
  max-height: 300px;

  margin: 0 auto;

  object-fit: contain;

  border: 1px solid #e2e8f0;
  border-radius: 8px;

  background: #ffffff;

  cursor: zoom-in;

  transition:
    max-width 0.25s ease,
    max-height 0.25s ease;
}


/* EXPANDED IMAGE */

.attachment-image.attachment-image-expanded {
  width: auto;

  max-width: 100%;
  max-height: 700px;

  cursor: zoom-out;
}


.image-preview-message {
  display: flex;
  align-items: center;
  justify-content: center;

  gap: 6px;

  margin-top: 9px;

  color: #64748b;

  font-size: 11px;
}


.image-preview-message i {
  color: #2563eb;
}


/* ========================================
   NON-IMAGE DOCUMENT
   ======================================== */

.document-preview {
  display: flex;
  align-items: center;

  gap: 12px;

  padding: 13px;

  background: #ffffff;

  border: 1px solid #e2e8f0;
  border-radius: 8px;
}


.document-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 40px;
  height: 40px;

  border-radius: 8px;

  background: #f1f5f9;

  color: #475569;

  font-size: 20px;
}


.document-preview strong {
  display: block;

  color: #172554;

  font-size: 13px;
}


.document-preview p {
  margin: 3px 0 0 0;

  color: #64748b;

  font-size: 11px;
}


/* ========================================
   NO ATTACHMENTS
   ======================================== */

.no-attachments {
  display: flex;
  align-items: center;

  gap: 8px;

  padding: 12px 14px;

  background: #f8fafc;

  border: 1px dashed #cbd5e1;
  border-radius: 8px;

  color: #64748b;

  font-size: 13px;
}


/* ========================================
   HOD REMARKS
   ======================================== */

.remarks-box {
  margin-top: 5px;
}


.remarks-box label {
  display: block;

  margin-bottom: 8px;

  color: #172554;

  font-size: 14px;
  font-weight: 600;
}


.remarks-box textarea {
  display: block;

  width: 100%;
  min-height: 92px;

  padding: 12px 13px;

  resize: vertical;

  border: 1px solid #cbd5e1;
  border-radius: 9px;

  background: #ffffff;

  color: #0f172a;

  font-size: 14px;

  outline: none;

  box-sizing: border-box;
}


.remarks-box textarea:focus {
  border-color: #2563eb;

  box-shadow:
    0 0 0 2px rgba(37, 99, 235, 0.08);
}


/* ========================================
   BUTTONS
   ======================================== */

.action-row {
  display: flex;

  align-items: center;
  justify-content: flex-end;

  gap: 12px;

  margin-top: 20px;
}


.btn-reject,
.btn-approve {
  min-width: 110px;

  padding: 11px 22px;

  border: none;
  border-radius: 7px;

  color: #ffffff;

  font-size: 14px;
  font-weight: 600;

  cursor: pointer;

  transition:
    opacity 0.2s ease,
    transform 0.1s ease;
}


.btn-reject {
  background: #ef4444;
}


.btn-approve {
  background: #10b981;
}


.btn-reject:hover,
.btn-approve:hover {
  opacity: 0.9;
}


.btn-reject:active,
.btn-approve:active {
  transform: translateY(1px);
}


/* ========================================
   EMPTY STATE
   ======================================== */

.empty-state {
  padding: 55px 25px;

  text-align: center;

  background: #ffffff;

  border: 1px solid #dbe3ec;
  border-radius: 14px;
}


.empty-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 50px;
  height: 50px;

  margin: 0 auto 15px auto;

  border-radius: 50%;

  background: #ecfdf5;

  color: #059669;

  font-size: 22px;
  font-weight: 700;
}


.empty-state h3 {
  margin: 0 0 7px 0;

  color: #172554;

  font-size: 18px;
}


.empty-state p {
  margin: 0;

  color: #64748b;

  font-size: 14px;
}


/* ========================================
   RESPONSIVE DESIGN
   ======================================== */

@media (max-width: 900px) {

  .details-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}


@media (max-width: 600px) {

  .hod-approvals-page {
    padding: 15px 12px 35px 12px;
  }


  .page-header {
    flex-direction: column;
  }


  .back-link {
    margin-top: 0;
  }


  .page-header h2 {
    font-size: 24px;
  }


  .details-grid {
    grid-template-columns: 1fr;
  }


  .approval-card {
    padding: 16px;
  }


  .attachment-image {
    max-width: 100%;
    max-height: 250px;
  }


  .action-row {
    flex-direction: column-reverse;
  }


  .btn-reject,
  .btn-approve {
    width: 100%;
  }

}

sp_widget.script:
(function() {

    // =====================================
    // INITIAL DATA
    // =====================================

    data.departmentName = "";
    data.requests = [];
    data.message = "";
    data.success = false;


    var standardDepartmentId = "";
    var departmentCode = "";
    var customDepartmentId = "";


    var LEAVE_REQUEST_TABLE =
        'x_snc_unified_hr_0_leave_request';


    // =====================================
    // FORMAT FILE SIZE
    // =====================================

    function formatFileSize(bytes) {

        bytes = parseInt(bytes, 10);

        if (!bytes || bytes <= 0) {
            return "";
        }


        if (bytes < 1024) {

            return bytes + " B";
        }


        if (bytes < (1024 * 1024)) {

            return (
                bytes / 1024
            ).toFixed(1) + " KB";
        }


        if (bytes < (1024 * 1024 * 1024)) {

            return (
                bytes /
                (1024 * 1024)
            ).toFixed(1) + " MB";
        }


        return (
            bytes /
            (1024 * 1024 * 1024)
        ).toFixed(1) + " GB";
    }



    // =====================================
    // CHECK WHETHER ATTACHMENT IS IMAGE
    // =====================================

    function isImageAttachment(
        fileName,
        contentType
    ) {

        fileName =
            (fileName || "").toLowerCase();

        contentType =
            (contentType || "").toLowerCase();


        // MIME TYPE CHECK

        if (
            contentType.indexOf(
                'image/'
            ) === 0
        ) {

            return true;
        }


        // EXTENSION FALLBACK

        var imageExtensions = [
            '.png',
            '.jpg',
            '.jpeg',
            '.gif',
            '.bmp',
            '.webp'
        ];


        for (
            var i = 0;
            i < imageExtensions.length;
            i++
        ) {

            if (
                fileName.lastIndexOf(
                    imageExtensions[i]
                ) ===
                fileName.length -
                imageExtensions[i].length
            ) {

                return true;
            }
        }


        return false;
    }



    // =====================================
    // GET ATTACHMENTS FOR LEAVE REQUEST
    // =====================================

    function getLeaveAttachments(
        requestSysId
    ) {

        var attachments = [];


        var glideAttachment =
            new GlideSysAttachment();


        var attachmentGR =
            glideAttachment.getAttachments(
                LEAVE_REQUEST_TABLE,
                requestSysId
            );


        while (attachmentGR.next()) {


            var attachmentSysId =
                attachmentGR.getUniqueValue();


            var fileName =
                attachmentGR.getValue(
                    'file_name'
                ) || "";


            var contentType =
                attachmentGR.getValue(
                    'content_type'
                ) || "";


            var sizeBytes =
                attachmentGR.getValue(
                    'size_bytes'
                ) || "0";


            var isImage =
                isImageAttachment(
                    fileName,
                    contentType
                );


            attachments.push({

                sys_id:
                    attachmentSysId,

                file_name:
                    fileName,

                content_type:
                    contentType,

                size:
                    formatFileSize(
                        sizeBytes
                    ),

                is_image:
                    isImage,

                /*
                 * Used only as IMG source.
                 * We are NOT providing a
                 * download/View anchor.
                 */

                preview_url:
                    "/sys_attachment.do?sys_id=" +
                    attachmentSysId

            });

        }


        return attachments;
    }



    // =====================================
    // GET LOGGED-IN HOD DEPARTMENT
    // =====================================

    var userGR =
        new GlideRecord(
            'sys_user'
        );


    if (
        userGR.get(
            gs.getUserID()
        )
    ) {


        standardDepartmentId =
            userGR.getValue(
                'department'
            ) || "";


        data.departmentName =
            userGR.getDisplayValue(
                'department'
            ) || "";

    }


    if (!standardDepartmentId) {

        return;
    }



    // =====================================
    // GET STANDARD DEPARTMENT CODE
    // =====================================

    var deptGR =
        new GlideRecord(
            'cmn_department'
        );


    if (
        deptGR.get(
            standardDepartmentId
        )
    ) {

        departmentCode =
            deptGR.getValue(
                'id'
            ) || "";

    }


    if (!departmentCode) {

        return;
    }



    // =====================================
    // FIND CUSTOM DEPARTMENT
    // =====================================

    var customDeptGR =
        new GlideRecord(
            'x_snc_unified_hr_0_department'
        );


    customDeptGR.addQuery(
        'department_code',
        departmentCode
    );


    customDeptGR.setLimit(1);

    customDeptGR.query();


    if (customDeptGR.next()) {

        customDepartmentId =
            customDeptGR.getUniqueValue();

    }


    if (!customDepartmentId) {

        return;
    }



    // =====================================
    // HANDLE APPROVE / REJECT
    // =====================================

    if (
        input &&
        input.action &&
        input.sys_id
    ) {


        var requestGR =
            new GlideRecord(
                LEAVE_REQUEST_TABLE
            );


        // ---------------------------------
        // FIND LEAVE REQUEST
        // ---------------------------------

        if (
            !requestGR.get(
                input.sys_id
            )
        ) {

            data.message =
                "Leave request was not found.";

            return;
        }



        // ---------------------------------
        // SECURITY:
        // CHECK HOD DEPARTMENT
        // ---------------------------------

        if (
            requestGR.getValue(
                'department'
            ) !=
            customDepartmentId
        ) {

            data.message =
                "You cannot act on a request from another department.";

            return;
        }



        // ---------------------------------
        // MUST BE PENDING HOD
        // ---------------------------------

        if (
            requestGR.getValue(
                'status'
            ) !=
            'pending_hod'
        ) {

            data.message =
                "This request is no longer waiting for HOD approval.";

            return;
        }



        // ---------------------------------
        // CHECK CURRENT APPROVER
        // ---------------------------------

        if (
            requestGR.getValue(
                'current_approver'
            ) &&
            requestGR.getValue(
                'current_approver'
            ) !=
            gs.getUserID()
        ) {

            data.message =
                "You are not the current approver for this request.";

            return;
        }



        // =================================
        // SAVE HOD REMARKS
        // =================================

        requestGR.setValue(
            'hod_remarks',
            input.remarks || ""
        );


        requestGR.update();



        // =================================
        // FIND SERVICENOW APPROVAL RECORD
        // =================================

        var approvalGR =
            new GlideRecord(
                'sysapproval_approver'
            );


        approvalGR.addQuery(
            'approver',
            gs.getUserID()
        );


        approvalGR.addQuery(
            'state',
            'requested'
        );


        /*
         * Scoped application records
         * can be linked through document_id.
         */

        var approvalLinkQuery =
            approvalGR.addQuery(
                'document_id',
                requestGR.getUniqueValue()
            );


        /*
         * Some approvals can also
         * use sysapproval.
         */

        if (
            approvalGR.isValidField(
                'sysapproval'
            )
        ) {

            approvalLinkQuery
                .addOrCondition(
                    'sysapproval',
                    requestGR.getUniqueValue()
                );

        }


        approvalGR.orderByDesc(
            'sys_created_on'
        );


        approvalGR.setLimit(1);

        approvalGR.query();



        // ---------------------------------
        // APPROVAL RECORD NOT FOUND
        // ---------------------------------

        if (!approvalGR.next()) {

            data.message =
                "The active approval record could not be found.";

            return;
        }



        // =================================
        // APPROVE
        // =================================

        if (
            input.action ==
            'approve'
        ) {


            approvalGR.setValue(
                'state',
                'approved'
            );


            approvalGR.update();


            data.success = true;


            data.message =
                "Leave request approved successfully.";

        }



        // =================================
        // REJECT
        // =================================

        else if (
            input.action ==
            'reject'
        ) {


            approvalGR.setValue(
                'state',
                'rejected'
            );


            approvalGR.update();


            data.success = true;


            data.message =
                "Leave request rejected successfully.";

        }

    }



    // =====================================
    // LOAD PENDING HOD REQUESTS
    // =====================================

    var leaveGR =
        new GlideRecord(
            LEAVE_REQUEST_TABLE
        );


    // SAME DEPARTMENT

    leaveGR.addQuery(
        'department',
        customDepartmentId
    );


    // ONLY PENDING HOD

    leaveGR.addQuery(
        'status',
        'pending_hod'
    );


    // ONLY CURRENT HOD

    leaveGR.addQuery(
        'current_approver',
        gs.getUserID()
    );


    leaveGR.orderBy(
        'applied_on'
    );


    leaveGR.query();



    // =====================================
    // BUILD REQUEST LIST
    // =====================================

    while (leaveGR.next()) {


        var requestSysId =
            leaveGR.getUniqueValue();



        // ---------------------------------
        // GET ATTACHMENTS
        // ---------------------------------

        var requestAttachments =
            getLeaveAttachments(
                requestSysId
            );



        // ---------------------------------
        // ADD REQUEST TO DATA
        // ---------------------------------

        data.requests.push({


            sys_id:
                requestSysId,


            number:
                leaveGR.getDisplayValue(
                    'number'
                ),


            employee:
                leaveGR.getDisplayValue(
                    'requested_by'
                ),


            leave_type:
                leaveGR.getDisplayValue(
                    'leave_type'
                ),


            start_date:
                leaveGR.getDisplayValue(
                    'start_date'
                ),


            end_date:
                leaveGR.getDisplayValue(
                    'end_date'
                ),


            days:
                leaveGR.getDisplayValue(
                    'number_of_leave_days'
                ),


            reason:
                leaveGR.getDisplayValue(
                    'reason'
                ),


            status:
                leaveGR.getDisplayValue(
                    'status'
                ),


            remarks:
                leaveGR.getValue(
                    'hod_remarks'
                ) || "",


            // --------------------------------
            // ATTACHMENTS
            // --------------------------------

            attachments:
                requestAttachments

        });

    }

})();
